const all = $input.all();

const ok      = all.filter(i => i.json.status === 'ok');
const failed  = all.filter(i => i.json.status === 'error');
const skipped = all.filter(i => i.json.status === 'skipped' || i.json._no_items);

return [{
  json: {
    run_completed_at: new Date().toISOString(),
    total_new:        ok.length + failed.length,
    success:          ok.length,
    failed:           failed.length,
    skipped:          skipped.length,
    ok_items: ok.map(i => ({
      feed_id:  i.json.feed_id,
      doc_id:   i.json.doc_id,
      doc_type: i.json.doc_type,
      chunks:   i.json.chunk_count,
      title:    i.json.title,
    })),
    failed_items: failed.map(i => ({
      feed_id: i.json.feed_id,
      step:    i.json.step,
      url:     i.json.url || i.json.doc_id || '',
      detail:  (i.json.detail || '').substring(0, 200),
    })),
  }
}];
